const timeAgo = (iso) => {
  if (!iso) return "—";
  const s = Math.floor((Date.now() - new Date(iso)) / 1000);
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
};

const langColor = { Python: "#3572A5", JavaScript: "#F7DF1E", TypeScript: "#3178C6", Go: "#00ADD8", Rust: "#DEA584", null: "#8B949E" };

const Dot = ({ color, pulse }) => (
  <span style={{ display: "inline-block", width: 7, height: 7, borderRadius: "50%", background: color, flexShrink: 0 }} className={pulse ? "pulse-dot" : ""} />
);

const SectionHeader = ({ title, sub, action, c }) => (
  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 16 }}>
    <div>
      <div style={{ fontSize: 15, fontWeight: 600, color: c.text }}>{title}</div>
      {sub && <div style={{ fontSize: 12, color: c.textSub, marginTop: 2 }}>{sub}</div>}
    </div>
    {action}
  </div>
);

const Notification = ({ msg, type, onClose }) => {
  const icons = { success: "✓", error: "✕", info: "i", warning: "!" };
  const colors = { success: "#3FB950", error: "#F85149", info: "#388BFD", warning: "#D29922" };
  useEffect(() => { const t = setTimeout(onClose, 4000); return () => clearTimeout(t); }, [onClose]);
  return (
    <div className="notification">
      <div style={{ width: 28, height: 28, borderRadius: "50%", background: colors[type] + "20", color: colors[type], display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, fontSize: 14, flexShrink: 0 }}>{icons[type]}</div>
      <div style={{ flex: 1, fontSize: 13 }}>{msg}</div>
      <button onClick={onClose} style={{ background: "none", border: "none", color: "#8B949E", fontSize: 16, lineHeight: 1 }}>×</button>
    </div>
  );
};

// ─── LOGIN PAGE ───────────────────────────────────────────────────
function LoginPage({ onLogin, c }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleLogin = async () => {
    if (!username.trim() || !password.trim()) return;
    setLoading(true);
    setError("");
    try {
      const res = await axios.post(`${API}/auth/login`, { username, password });
      const token = res.data.access_token;
      localStorage.setItem("jwt_token", token);
      localStorage.setItem("jwt_username", res.data.username);
      axios.defaults.headers.common["Authorization"] = `Bearer ${token}`;
      onLogin(res.data.username);
    } catch (err) {
      setError(err.response?.data?.detail || "Invalid username or password");
    }
    setLoading(false);
  };

  return (
    <div style={{ minHeight: "100vh", background: c.bg, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ width: 380, background: c.card, border: `1px solid ${c.border}`, borderRadius: 12, padding: 32 }} className="fade-in">
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 32 }}>
          <div style={{ width: 36, height: 36, background: `linear-gradient(135deg, ${c.accent}, ${c.purple})`, borderRadius: 9, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <div style={{ width: 12, height: 12, borderRadius: "50%", background: "rgba(255,255,255,.9)" }} />
          </div>
          <div>
            <div style={{ fontSize: 15, fontWeight: 600, color: c.text }}>GitHub Review Agent</div>
            <div style={{ fontSize: 11, color: c.textMuted }}>Smartovate Ltd · 2026</div>
          </div>
        </div>

        <div style={{ fontSize: 20, fontWeight: 700, color: c.text, marginBottom: 6 }}>Sign in</div>
        <div style={{ fontSize: 13, color: c.textSub, marginBottom: 24 }}>Enter your credentials to access the dashboard</div>

        <div style={{ marginBottom: 16 }}>
          <label style={{ fontSize: 12, color: c.textSub, display: "block", marginBottom: 6 }}>Username</label>
          <input
            className="input"
            value={username}
            onChange={e => setUsername(e.target.value)}
            onKeyDown={e => e.key === "Enter" && handleLogin()}
            placeholder="admin"
            autoFocus
          />
        </div>

        <div style={{ marginBottom: 24 }}>
          <label style={{ fontSize: 12, color: c.textSub, display: "block", marginBottom: 6 }}>Password</label>
          <input
            className="input"
            type="password"
            value={password}
            onChange={e => setPassword(e.target.value)}
            onKeyDown={e => e.key === "Enter" && handleLogin()}
            placeholder="••••••••"
          />
        </div>

        {error && (
          <div style={{ background: c.danger + "15", border: `1px solid ${c.danger}40`, borderRadius: 8, padding: "10px 14px", fontSize: 13, color: c.danger, marginBottom: 16 }}>
            {error}
          </div>
        )}

        <button
          className="btn btn-primary"
          style={{ width: "100%", justifyContent: "center", padding: "10px 14px" }}
          onClick={handleLogin}
          disabled={loading || !username.trim() || !password.trim()}
        >
          {loading ? <><div className="spinner" />Signing in...</> : "Sign in"}
        </button>
      </div>
    </div>
  );
}

