// ─── Main App ─────────────────────────────────────────────────────
export default function App() {
  const [theme, setTheme] = useState("dark");
  const [page, setPage] = useState("dashboard");
  const [collapsed, setCollapsed] = useState(false);
  const [online, setOnline] = useState(false);
  const [metrics, setMetrics] = useState({ total_prs: 0, analysed: 0, oversized: 0, bugs_detected: 0 });
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("Nour-Faker/github-review-agent");
  const [pulls, setPulls] = useState([]);
  const [loadingPulls, setLoadingPulls] = useState(false);
  const [triggering, setTriggering] = useState(null);
  const [notification, setNotification] = useState(null);
  const [clock, setClock] = useState(new Date().toLocaleTimeString());

  // ─── Auth state ───────────────────────────────────────────────
  const [loggedIn, setLoggedIn] = useState(false);
  const [username, setUsername] = useState("");

  // Restore session on load
  useEffect(() => {
    const token = localStorage.getItem("jwt_token");
    const savedUser = localStorage.getItem("jwt_username");
    if (token) {
      axios.defaults.headers.common["Authorization"] = `Bearer ${token}`;
      setLoggedIn(true);
      setUsername(savedUser || "admin");
    }
  }, []);

  const handleLogin = (user) => {
    setLoggedIn(true);
    setUsername(user);
  };

  const handleLogout = () => {
    localStorage.removeItem("jwt_token");
    localStorage.removeItem("jwt_username");
    delete axios.defaults.headers.common["Authorization"];
    setLoggedIn(false);
    setUsername("");
  };

  const c = T[theme];
  const notify = (msg, type = "info") => setNotification({ msg, type });

  useEffect(() => {
    document.documentElement.style.setProperty("--card", c.card);
    document.documentElement.style.setProperty("--border", c.border);
  }, [c]);

  useEffect(() => {
    if (!loggedIn) return;
    axios.get(`${API}/health`).then(() => setOnline(true)).catch(() => setOnline(false));
    axios.get(`${API}/api/metrics`)
      .then(r => setMetrics(r.data))
      .catch(() => notify("Unable to load metrics", "error"));
    axios.get(`${API}/api/repos`)
      .then(r => setRepos(r.data.repos || []))
      .catch(() => notify("Unable to load repositories", "error"));
    const t = setInterval(() => setClock(new Date().toLocaleTimeString()), 1000);
    return () => clearInterval(t);
  }, [loggedIn]);

  useEffect(() => {
    if (!selectedRepo || !loggedIn) return;
    setLoadingPulls(true);
    const [owner, repo] = selectedRepo.split("/");
    axios.get(`${API}/api/repos/${owner}/${repo}/pulls`)
      .then(r => setPulls(r.data.pulls || []))
      .catch(() => {
        setPulls([]);
        notify("Unable to load PRs", "error");
      })
      .finally(() => setLoadingPulls(false));
  }, [selectedRepo, loggedIn]);

  const handleTrigger = useCallback(async (repo, prNumber) => {
    const key = `${repo}#${prNumber}`;
    setTriggering(key);
    try {
      const [owner, repoName] = repo.split("/");
      await axios.post(`${API}/api/trigger/${owner}/${repoName}/${prNumber}`);
      notify(`Agent triggered on PR #${prNumber} — analysis in progress`, "success");
    } catch {
      notify(`Failed to trigger agent on PR #${prNumber}`, "error");
    }
    setTriggering(null);
  }, []);

  // ─── Show login if not authenticated ─────────────────────────
  if (!loggedIn) {
    return (
      <>
        <GlobalCSS c={c} />
        <LoginPage onLogin={handleLogin} c={c} />
      </>
    );
  }

  const NAV = [
    { id: "dashboard", label: "Dashboard", icon: "▣" },
    { id: "repos", label: "Repositories", icon: "⊞" },
    { id: "reviews", label: "Reviews", icon: "◈" },
    { id: "analytics", label: "Analytics", icon: "◎" },
    { id: "settings", label: "Settings", icon: "◉" },
  ];

  return (
    <>
      <GlobalCSS c={c} />
      <div style={{ display: "flex", minHeight: "100vh", background: c.bg }}>

        <aside style={{ width: collapsed ? 56 : 220, background: c.surface, borderRight: `1px solid ${c.border}`, display: "flex", flexDirection: "column", position: "fixed", height: "100vh", transition: "width .2s cubic-bezier(.4,0,.2,1)", overflow: "hidden", zIndex: 20 }}>
          <div style={{ padding: collapsed ? "16px 12px" : "16px 16px", display: "flex", alignItems: "center", justifyContent: collapsed ? "center" : "space-between", borderBottom: `1px solid ${c.border}`, minHeight: 57 }}>
            {!collapsed && (
              <div style={{ display: "flex", alignItems: "center", gap: 10, overflow: "hidden" }}>
                <div style={{ width: 28, height: 28, background: `linear-gradient(135deg, ${c.accent}, ${c.purple})`, borderRadius: 7, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <div style={{ width: 10, height: 10, borderRadius: "50%", background: "rgba(255,255,255,.9)" }} />
                </div>
                <div style={{ overflow: "hidden" }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: c.text, whiteSpace: "nowrap" }}>Review Agent</div>
                  <div className="mono" style={{ fontSize: 10, color: c.textMuted }}>v1.0 · prod</div>
                </div>
              </div>
            )}
            <button onClick={() => setCollapsed(v => !v)} style={{ background: "none", border: "none", color: c.textMuted, fontSize: 14, padding: 4, flexShrink: 0, lineHeight: 1 }}>
              {collapsed ? "»" : "«"}
            </button>
          </div>

          <nav style={{ padding: "10px 8px", flex: 1 }}>
            {!collapsed && <div style={{ fontSize: 10, color: c.textMuted, padding: "0 8px", marginBottom: 6, letterSpacing: ".08em" }}>MENU</div>}
            {NAV.map(n => (
              <div key={n.id} className={`nav-link ${page === n.id ? "active" : ""}`}
                style={{ justifyContent: collapsed ? "center" : "flex-start", padding: collapsed ? "10px" : "7px 12px" }}
                onClick={() => setPage(n.id)} title={collapsed ? n.label : ""}>
                <span style={{ fontSize: 15, flexShrink: 0 }}>{n.icon}</span>
                {!collapsed && <span className="slide-in">{n.label}</span>}
              </div>
            ))}
          </nav>

          {!collapsed && (
            <div style={{ padding: "12px 12px", borderTop: `1px solid ${c.border}` }}>
              <div style={{ background: c.card, border: `1px solid ${c.border}`, borderRadius: 8, padding: "10px 12px", marginBottom: 8 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                  <span className="mono" style={{ fontSize: 11, color: c.accent }}>GPT-5-mini</span>
                  <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
                    <Dot color={online ? c.success : c.danger} pulse={online} />
                    <span style={{ fontSize: 10, color: online ? c.success : c.danger }}>{online ? "Live" : "Offline"}</span>
                  </div>
                </div>
                <div style={{ fontSize: 10, color: c.textMuted }}>Azure OpenAI · Sweden Central</div>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span style={{ fontSize: 11, color: c.textSub }}>👤 {username}</span>
                <button className="btn btn-danger" style={{ fontSize: 11, padding: "3px 10px" }} onClick={handleLogout}>Logout</button>
              </div>
            </div>
          )}
        </aside>

        <main style={{ marginLeft: collapsed ? 56 : 220, flex: 1, transition: "margin-left .2s cubic-bezier(.4,0,.2,1)", display: "flex", flexDirection: "column", minHeight: "100vh" }}>
          <header style={{ height: 57, borderBottom: `1px solid ${c.border}`, display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 24px", position: "sticky", top: 0, background: c.surface, zIndex: 10, backdropFilter: "blur(8px)" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <h1 style={{ fontSize: 15, fontWeight: 600 }}>{NAV.find(n => n.id === page)?.label}</h1>
              {selectedRepo && page !== "settings" && (
                <span className="tag mono" style={{ marginLeft: 8 }}>{selectedRepo}</span>
              )}
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <span className="mono" style={{ fontSize: 11, color: c.textMuted }}>{clock}</span>
              <span className={`badge ${online ? "badge-green" : "badge-red"}`}>
                <Dot color={online ? c.success : c.danger} />{online ? "Online" : "Offline"}
              </span>
              <button className="btn btn-secondary" style={{ fontSize: 12 }} onClick={() => setTheme(t => t === "dark" ? "light" : "dark")}>
                {theme === "dark" ? "Light" : "Dark"}
              </button>
              <a href={`${API}/docs`} target="_blank" rel="noreferrer">
                <button className="btn btn-secondary" style={{ fontSize: 12 }}>API</button>
              </a>
            </div>
          </header>

          <div style={{ flex: 1, padding: 24, maxWidth: 1200, width: "100%" }}>
            {page === "dashboard" && <Dashboard c={c} online={online} metrics={metrics} repos={repos} selectedRepo={selectedRepo} pulls={pulls} loadingPulls={loadingPulls} />}
            {page === "repos" && <ReposPage c={c} repos={repos} selectedRepo={selectedRepo} setSelectedRepo={setSelectedRepo} pulls={pulls} loadingPulls={loadingPulls} onTrigger={handleTrigger} triggering={triggering} />}
            {page === "reviews" && <ReviewsPage c={c} />}
            {page === "analytics" && <AnalyticsPage c={c} metrics={metrics} />}
            {page === "settings" && <SettingsPage c={c} online={online} theme={theme} setTheme={setTheme} />}
          </div>

          <footer style={{ padding: "12px 24px", borderTop: `1px solid ${c.border}`, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span className="mono" style={{ fontSize: 11, color: c.textMuted }}>GitHub Review Agent · Smartovate LTD · Nour Faker · 2026</span>
            <a href={`${GITHUB}/Nour-Faker/github-review-agent`} target="_blank" rel="noreferrer" style={{ fontSize: 11, color: c.accent }}>View on GitHub</a>
          </footer>
        </main>

        {notification && <Notification msg={notification.msg} type={notification.type} onClose={() => setNotification(null)} />}
      </div>
    </>
  );
}